INSERT INTO public.assessment_versions(id,number,label,config,state) VALUES('b83c9a0c-42b1-4093-83ac-a46808cc6889',1,'Tahap I · Angkatan 2024','{"label":"Tahap I · Angkatan 2024","penalty":1,"slots":["lab","rumah"],"meetings":[{"id":"meeting-1","name":"Pertemuan 1","date":"","active":true},{"id":"meeting-2","name":"Pertemuan 2","date":"","active":true},{"id":"meeting-3","name":"Pertemuan 3","date":"","active":true},{"id":"meeting-4","name":"Pertemuan 4","date":"","active":true},{"id":"meeting-5","name":"Pertemuan 5","date":"","active":true}],"aspects":[{"code":"A1","name":"Ketepatan waktu pengumpulan","max":10,"group":"Administrasi","kind":"submission-time","active":true,"criteria":[]},{"code":"A2","name":"Kondisi isi saat pengumpulan","max":10,"group":"Administrasi","kind":"submission-content","active":true,"criteria":[]},{"code":"B1","name":"Latar belakang","max":6,"group":"Substansi","kind":"criterion","active":true,"criteria":[{"level":"Sangat Baik","min":6,"max":6,"description":"Menjelaskan kondisi nyata studi kasus, permasalahan jelas dan didukung data/fakta, alasan perlunya sistem informasi logis."},{"level":"Baik","min":4,"max":5,"description":"Permasalahan jelas, tetapi data/fakta pendukung terbatas."},{"level":"Cukup","min":2,"max":3,"description":"Uraian bersifat umum dan kurang terkait studi kasus."},{"level":"Kurang","min":0,"max":1,"description":"Tidak relevan atau tidak ada."}]},{"code":"B2","name":"Rumusan masalah, tujuan, dan manfaat","max":5,"group":"Substansi","kind":"criterion","active":true,"criteria":[{"level":"Sangat Baik","min":5,"max":5,"description":"Rumusan spesifik, setiap tujuan menjawab rumusan masalah, manfaat jelas bagi pihak terkait."},{"level":"Baik","min":4,"max":4,"description":"Lengkap, tetapi keterkaitan rumusan dan tujuan kurang tegas."},{"level":"Cukup","min":2,"max":3,"description":"Salah satu bagian belum ada atau terlalu umum."},{"level":"Kurang","min":0,"max":1,"description":"Tidak sesuai atau tidak ada."}]},{"code":"B3","name":"Tinjauan pustaka","max":7,"group":"Substansi","kind":"criterion","active":true,"criteria":[{"level":"Sangat Baik","min":7,"max":7,"description":"Membahas konsep sistem informasi, DFD, ERD, dan UML; referensi relevan minimal 5 sumber; sitasi APA konsisten."},{"level":"Baik","min":5,"max":6,"description":"Konsep lengkap, referensi relevan tetapi kurang dari 5 sumber atau sitasi kurang konsisten."},{"level":"Cukup","min":3,"max":4,"description":"Konsep tidak lengkap, referensi minim atau tidak disitasi dengan benar."},{"level":"Kurang","min":0,"max":2,"description":"Tanpa referensi atau tidak relevan."}]},{"code":"B4","name":"Identifikasi aktor dan kebutuhan pengguna","max":7,"group":"Substansi","kind":"criterion","active":true,"criteria":[{"level":"Sangat Baik","min":7,"max":7,"description":"Seluruh aktor teridentifikasi beserta perannya; kebutuhan fungsional dan nonfungsional dirinci per aktor dan sesuai studi kasus."},{"level":"Baik","min":5,"max":6,"description":"Aktor lengkap, kebutuhan kurang rinci atau tidak dipisahkan antara fungsional dan nonfungsional."},{"level":"Cukup","min":3,"max":4,"description":"Terdapat aktor yang terlewat atau kebutuhan terlalu umum."},{"level":"Kurang","min":0,"max":2,"description":"Tidak sesuai studi kasus atau tidak ada."}]},{"code":"B5","name":"Data Flow Diagram (DFD)","max":11,"group":"Substansi","kind":"criterion","active":true,"criteria":[{"level":"Sangat Baik","min":10,"max":11,"description":"Diagram konteks dan DFD level 0/1 lengkap; notasi benar; entitas eksternal sesuai aktor; aliran data diberi nama; seimbang (balancing) antarlevel; data store konsisten."},{"level":"Baik","min":7,"max":9,"description":"Lengkap, terdapat kesalahan minor pada notasi, penamaan, atau balancing."},{"level":"Cukup","min":4,"max":6,"description":"Hanya sebagian level, beberapa aliran atau proses tidak logis."},{"level":"Kurang","min":0,"max":3,"description":"Notasi salah secara umum, tidak menggambarkan sistem, atau tidak ada."}]},{"code":"B6","name":"Entity Relationship Diagram (ERD)","max":11,"group":"Substansi","kind":"criterion","active":true,"criteria":[{"level":"Sangat Baik","min":10,"max":11,"description":"Entitas dan atribut lengkap; primary key dan foreign key tepat; relasi dan kardinalitas benar; konsisten dengan data store pada DFD."},{"level":"Baik","min":7,"max":9,"description":"Lengkap, terdapat kesalahan minor pada kardinalitas atau atribut kunci."},{"level":"Cukup","min":4,"max":6,"description":"Entitas/atribut kurang lengkap, relasi atau kardinalitas banyak yang keliru."},{"level":"Kurang","min":0,"max":3,"description":"Tidak sesuai kaidah ERD atau tidak ada."}]},{"code":"B7","name":"Activity Diagram (UML)","max":8,"group":"Substansi","kind":"criterion","active":true,"criteria":[{"level":"Sangat Baik","min":7,"max":8,"description":"Proses utama tergambar; menggunakan swimlane per aktor; notasi (initial, action, decision, fork/join, final) benar; alur logis dan konsisten dengan DFD serta kebutuhan pengguna."},{"level":"Baik","min":5,"max":6,"description":"Proses utama tergambar, terdapat kesalahan minor notasi atau tanpa swimlane."},{"level":"Cukup","min":3,"max":4,"description":"Hanya sebagian proses, alur kurang logis."},{"level":"Kurang","min":0,"max":2,"description":"Notasi salah, tidak sesuai sistem, atau tidak ada."}]},{"code":"C","name":"Tata tulis dan format","max":5,"group":"Tata Tulis","kind":"criterion","active":true,"criteria":[{"level":"Sangat Baik","min":5,"max":5,"description":"Sistematika sesuai template, gambar/tabel bernomor dan berjudul, diagram terbaca jelas, bahasa baku."},{"level":"Baik","min":4,"max":4,"description":"Terdapat kesalahan minor penomoran atau bahasa."},{"level":"Cukup","min":2,"max":3,"description":"Sistematika tidak runtut, beberapa diagram sulit dibaca."},{"level":"Kurang","min":0,"max":1,"description":"Tidak mengikuti template."}]},{"code":"D1","name":"Kesungguhan dan keaktifan","max":10,"group":"Sikap","kind":"average","active":true,"criteria":[{"level":"Sangat Baik","min":9,"max":10,"description":"Fokus mengerjakan tugas praktikum dari awal sampai akhir sesi, aktif bertanya atau berdiskusi, dan target tugas sesi tercapai."},{"level":"Baik","min":7,"max":8,"description":"Mengerjakan tugas dengan sungguh-sungguh, tetapi kurang aktif atau target tugas sesi belum sepenuhnya tercapai."},{"level":"Cukup","min":4,"max":6,"description":"Mengerjakan tugas, tetapi sering tidak fokus dan perlu diingatkan lebih dari satu kali."},{"level":"Kurang","min":0,"max":3,"description":"Hampir tidak mengerjakan tugas praktikum selama sesi atau tidak hadir tanpa keterangan."}]},{"code":"D2","name":"Kepatuhan tata tertib praktikum","max":10,"group":"Sikap","kind":"deduction","active":true,"criteria":[]}],"violations":[{"code":"P1","name":"Bermain HP untuk keperluan di luar praktikum (media sosial, chat, game, video) selama sesi berlangsung.","penalty":1,"active":true},{"code":"P2","name":"Menonton video, membuka media sosial, bermain game, atau membuka situs hiburan di komputer praktikum.","penalty":1,"active":true},{"code":"P3","name":"Tidak mengerjakan tugas praktikum selama sesi (mengerjakan tugas mata kuliah lain, hanya diam, atau tidur).","penalty":2,"active":true},{"code":"P4","name":"Terlambat hadir lebih dari 15 menit tanpa alasan yang dapat diterima.","penalty":1,"active":true},{"code":"P5","name":"Meninggalkan ruang praktikum tanpa izin atau pulang sebelum sesi selesai.","penalty":1,"active":true},{"code":"P6","name":"Membuat gaduh atau mengganggu mahasiswa lain yang sedang mengerjakan tugas.","penalty":1,"active":true},{"code":"P7","name":"Menyalin pekerjaan mahasiswa atau kelompok lain dan mengakuinya sebagai hasil sendiri.","penalty":2,"active":true},{"code":"P8","name":"Tidak hadir praktikum tanpa keterangan.","penalty":2,"active":true}]}'::jsonb,'active');
